``` math
\begin{equation}
 D_{N+r}\in-B_{h,N,r}+2^{r+1}\mathbb{Z}\quad\Longleftrightarrow\quad D_N\in2\mathbb{Z}.
\label{eq:affinecollapse}\ltx@label{long251:eq:affinecollapse}
